201	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
202	  constexpr int kPollMs = 50;
203	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
204	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
205	      char line[512];
206	      while (std::fgets(line, sizeof line, f)) {
207	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
208	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
209	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
210	        unsigned lport = 0, st = 0;
211	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
212	            && st == 0x0A && lport == port) {
213	          std::fclose(f);
214	          return true;
215	        }
216	      }
217	      std::fclose(f);
218	    }
219	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
220	  }
221	  return false;
