378	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
379	                    "; raise --mem-size or shrink the image",
380	                    static_cast<unsigned long long>(top),
381	                    static_cast<unsigned long long>(scratch_gpa));
382	      return fail(msg);
383	    }
384	  }
